const assert = require('node:assert/strict');
const fs = require('node:fs'), os = require('node:os'), path = require('node:path');
const {spawn, spawnSync} = require('node:child_process');
const profile = fs.mkdtempSync(path.join(os.tmpdir(), 'gnci-alumni-'));
const browser = spawn('C:/Program Files/Google/Chrome/Application/chrome.exe', ['--headless=new', '--disable-gpu', '--no-first-run', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {windowsHide:true, stdio:'ignore'});
const delay = ms => new Promise(r=>setTimeout(r,ms));
async function until(fn, label) { for(let end=Date.now()+30000; Date.now()<end;) { if(await fn()) return; await delay(150); } throw Error(label); }
let socket, session, cleanupCrop;
(async()=>{
    await until(()=>fs.existsSync(path.join(profile,'DevToolsActivePort')), 'Chrome not ready');
    const port=fs.readFileSync(path.join(profile,'DevToolsActivePort'),'utf8').split('\n')[0];
    const tabs=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    socket=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
    await new Promise(r=>socket.addEventListener('open',r,{once:true}));
    let serial=0; const pending=new Map();
    socket.addEventListener('message',event=>{ const p=JSON.parse(event.data); if(p.id&&pending.has(p.id)){pending.get(p.id)(p);pending.delete(p.id);} });
    const send=(method,params={})=>new Promise((resolve,reject)=>{ const id=++serial;pending.set(id,p=>p.error?reject(Error(JSON.stringify(p.error))):resolve(p.result));socket.send(JSON.stringify({id,method,params})); });
    const evaluate=async expression=>{ const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value; };
    await send('Page.enable'); await send('Network.enable');
    const visit=async route=>{await send('Page.navigate',{url:'http://localhost:8080'+route});await until(()=>evaluate("document.readyState==='complete'"),'Page not ready');await delay(2200);await evaluate("document.querySelector('#gncSiteDisclaimer form button')?.click();document.querySelector('[data-privacy-action=\"reject\"]')?.click()");};
    for(const width of [1440,820,390]) {
        await send('Emulation.setDeviceMetricsOverride',{width,height:950,deviceScaleFactor:1,mobile:false});
        await visit('/alumni');
        assert.match(await evaluate("document.querySelector('h1').innerText"),/Your story/);
        assert.equal(await evaluate("document.querySelectorAll('.alumni-actions a').length"),2);
        assert.equal(await evaluate("Boolean(document.querySelector('#alumni-stories'))"),false);
        assert.equal(await evaluate("document.documentElement.scrollWidth<=innerWidth"),true);
        assert.match(await evaluate("getComputedStyle(document.querySelector('#alumni-hero')).backgroundImage"),/url\(/);
        fs.writeFileSync(`cache/alumni-${width}.png`,Buffer.from((await send('Page.captureScreenshot',{format:'png'})).data,'base64'));
    }
    await visit('/alumni?ce_preview=1');
    assert.equal(await evaluate("document.querySelectorAll('[data-ve-section]').length"),0,'Anonymous preview must not expose editing markers');
    const denied=await evaluate("fetch('/admin/action/page-content-handler.php',{method:'POST',body:new URLSearchParams({action:'save_draft',page:'alumni',section_key:'intro',content:'unauthorized'})}).then(r=>({url:r.url,status:r.status}))");
    assert.ok(/login/.test(denied.url)||denied.status===403||denied.status===401);
    const php=spawnSync('docker',['compose','exec','-T','--user','www-data','web','php','cache/activity-log-session.php','Super Admin'],{encoding:'utf8',windowsHide:true});
    if(php.status!==0)throw Error(php.stderr||php.stdout); session=JSON.parse(php.stdout);
    await send('Network.setCookie',{...session,url:'http://localhost:8080',httpOnly:true});
    await send('Emulation.setDeviceMetricsOverride',{width:1440,height:1000,deviceScaleFactor:1,mobile:false});
    await visit('/admin/content-edit.php?page=alumni');
    await until(()=>evaluate("Boolean(document.querySelector('iframe')?.contentDocument?.querySelector('[data-ve-section=\"intro\"][contenteditable]'))"),'Editable alumni preview unavailable');
    assert.equal(await evaluate("document.querySelector('iframe').contentDocument.querySelectorAll('[data-ve-section][contenteditable]').length"),8);
    assert.match(await evaluate("document.querySelector('iframe').contentDocument.body.innerText"),/Your story/);
    assert.equal(await evaluate("Boolean(document.querySelector('iframe').contentWindow.GNCResponsiveBackgrounds.target(document.querySelector('iframe').contentDocument.getElementById('alumni-hero')))"),true,'Hero must support Background controls');
    await evaluate("document.querySelector('iframe').contentDocument.querySelector('[data-ve-background-for]').click()");
    await until(()=>evaluate("!document.getElementById('vePop').hidden && [...document.querySelectorAll('#vePop button')].some(b=>b.textContent==='Replace desktop background')"),'Background replacement controls must open');
    assert.equal(await evaluate("document.getElementById('veTb').hidden"),false);
    await send('Page.setInterceptFileChooserDialog',{enabled:true});
    await evaluate("[...document.querySelectorAll('#vePop button')].find(b=>b.textContent==='Replace desktop background').click()");
    const root=await send('DOM.getDocument');
    const fileInput=await send('DOM.querySelector',{nodeId:root.root.nodeId,selector:'#veFile'});
    await send('DOM.setFileInputFiles',{nodeId:fileInput.nodeId,files:[path.resolve('assets/images/gnc-header.png')]});
    await until(()=>evaluate("getComputedStyle(document.querySelector('iframe').contentDocument.getElementById('alumni-hero')).backgroundImage.includes('blob:')"),'Selected image must replace the background in preview');
    assert.equal(await evaluate("document.getElementById('veSaveDraft').disabled"),false,'Background replacement must enable saving');
    const initialY=await evaluate("parseFloat(getComputedStyle(document.querySelector('iframe').contentDocument.getElementById('alumni-hero')).backgroundPosition.split(' ')[1])");
    await evaluate("window.alumniCropPromise=GNCImageFraming.edit(document.querySelector('iframe').contentDocument.getElementById('alumni-hero'));true");
    await until(()=>evaluate("Boolean(document.querySelector('.image-frame-dialog[open]'))"),'Uploaded background must open crop dialog');
    await evaluate("let zoom=document.querySelector('.image-frame-dialog [aria-label=\"Image zoom\"]');zoom.value='1.75';zoom.dispatchEvent(new Event('input',{bubbles:true}));let preview=document.querySelector('.image-frame-preview');preview.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowUp',bubbles:true}));document.querySelector('.image-frame-save').click()");
    await until(()=>evaluate("!document.querySelector('.image-frame-dialog')"),'Use position must close crop dialog');
    const crop=await evaluate("(()=>{let w=document.querySelector('iframe').contentWindow,t=w.GNCResponsiveBackgrounds.target(w.document.getElementById('alumni-hero'));return w.GNCResponsiveBackgrounds.frame(t)})()");
    assert.equal(crop.zoom,1.75,'Use position must update responsive background zoom');
    assert.equal(crop.y,Math.min(100,initialY+2),'Use position must retain vertical position');
    const size=await evaluate("getComputedStyle(document.querySelector('iframe').contentDocument.getElementById('alumni-hero')).backgroundSize");
    assert.match(size,/px/,'Responsive crop must apply zoom to the hero');
    assert.equal(await evaluate("GNCImageFraming.findTarget(document.querySelector('iframe').contentDocument.getElementById('alumni-hero'))?.id"),'alumni-hero','Zoomed background must remain repositionable');
    assert.equal(await evaluate("VEImageFraming.background(document.querySelector('iframe').contentDocument.getElementById('alumni-hero'))"),true,'Reposition shortcut must open background controls');
    const csrf=await evaluate("fetch('/admin/action/page-content-handler.php',{method:'POST',body:new URLSearchParams({action:'save_draft',page:'alumni',section_key:'intro',content:'invalid csrf'})}).then(r=>r.json())");
    assert.equal(csrf.success,false);assert.match(csrf.error,/session.*expired/i);
    fs.writeFileSync('cache/alumni-editor.png',Buffer.from((await send('Page.captureScreenshot',{format:'png'})).data,'base64'));
    const testRoute='/pages/alumni.php?crop_test='+Date.now(), token=await evaluate('VE_CONFIG.csrf');
    const persist=async changes=>evaluate(`fetch('/admin/action/responsive-background-handler.php',{method:'POST',body:new URLSearchParams({csrf_token:${JSON.stringify(token)},route:${JSON.stringify(testRoute)},changes:${JSON.stringify(JSON.stringify(changes))}})}).then(r=>r.json())`);
    cleanupCrop=()=>persist({'#alumni-hero':{desktop:null}});
    const saved=await persist({'#alumni-hero':{desktop:{...crop,path:'/assets/images/gnc-header.png'}}});
    assert.equal(saved.success,true,'Position publishing must succeed');
    assert.equal(saved.settings['#alumni-hero'].desktop.y,crop.y);
    assert.equal(saved.settings['#alumni-hero'].desktop.zoom,crop.zoom);
    await visit('/alumni?'+testRoute.split('?')[1]);
    assert.equal(await evaluate("getComputedStyle(document.getElementById('alumni-hero')).backgroundPosition"),crop.x+'% '+crop.y+'%','Published position must match the crop preview');
    await until(()=>evaluate("getComputedStyle(document.getElementById('alumni-hero')).backgroundSize.includes('px')"),'Published zoom must restore after reload');
    assert.equal(await evaluate("getComputedStyle(document.getElementById('alumni-hero')).backgroundSize"),size,'Published crop dimensions must match the editor preview');
    assert.equal((await cleanupCrop()).success,true);cleanupCrop=null;
    console.log('PASS: layouts, permissions, replacement, Use position, retained crop, zoomed-image re-editing, published position and zoom after reload. Isolated test settings removed.');
})().catch(error=>{console.error(error);process.exitCode=1;}).finally(async()=>{
    if(cleanupCrop)await cleanupCrop();
    socket?.close();browser.kill();
    if(session)spawnSync('docker',['compose','exec','-T','--user','www-data','web','php','cache/activity-log-session.php','destroy',session.value],{windowsHide:true});
});
